using System;using System.IO;using System.Collections.Generic;using UnityEngine;
public class Script{public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");var rows=new List<object>();foreach(var mode in new[]{ParticleSystemShapeMultiModeValue.Random,ParticleSystemShapeMultiModeValue.Loop,ParticleSystemShapeMultiModeValue.PingPong,ParticleSystemShapeMultiModeValue.BurstSpread})foreach(var radius in new[]{1f,2.25f})foreach(var speed in new[]{1f,10f})foreach(var burst in new[]{false,true}){var go=new GameObject("edge-probe"){hideFlags=HideFlags.HideAndDontSave};try{var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var m=ps.main;m.playOnAwake=false;m.startSpeed=0;m.startLifetime=10;m.duration=1;var e=ps.emission;e.enabled=true;e.rateOverTime=burst?0:20;if(burst)e.SetBursts(new[]{new ParticleSystem.Burst(0,5)});var sh=ps.shape;sh.enabled=true;sh.shapeType=ParticleSystemShapeType.SingleSidedEdge;sh.radius=radius;sh.radiusMode=mode;sh.radiusSpeed=speed;ps.useAutoRandomSeed=false;ps.randomSeed=12345;ps.Play();ps.Pause();var frames=new List<object>();for(int i=1;i<=12;i++){ps.Simulate(.05f,false,false,false);var p=new ParticleSystem.Particle[64];var count=ps.GetParticles(p);var positions=new List<object>();for(int j=0;j<count;j++)positions.Add(new{seed=p[j].randomSeed,position=new[]{p[j].position.x,p[j].position.y,p[j].position.z}});frames.Add(new{frame=i,time=ps.time,particles=positions});}rows.Add(new{mode=(int)mode,radius,speed,burst,frames});}finally{UnityEngine.Object.DestroyImmediate(go);}}File.WriteAllText("OUTPUT_FILE",System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,unityVersion=Application.unityVersion,rows}));return "Edge cases="+rows.Count;}}
